#nullable enable // autogenerated

using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;
using PVZEngine.SeedPacks;

namespace MVZ2.GameContent.Buffs.SeedPacks
{
    [AutoBuffDefinition(VanillaBuffNames.SeedPack.temperanceCostReduction)]
    public class TemperanceCostReductionBuff : BuffDefinition
    {
        public TemperanceCostReductionBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(EngineSeedProps.COST, NumberOperator.Add, -50));
        }
    }
}
